// @vitest-environment node
import fs from "node:fs";
import sharp from "sharp";
import { describe, it, expect } from "vitest";

// The installable app's icons, generated by scripts/build-icons.mjs from design/icon/good-shepherd.svg.
const FIELD = [0xe8, 0xdc, 0xc3];

async function pixels(path: string) {
  const { data, info } = await sharp(path).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  return { data, width: info.width, height: info.height };
}

describe("app icons", () => {
  it("each icon has its stated size", async () => {
    const sizes: Record<string, number> = {
      "public/app-icons/icon-192.png": 192,
      "public/app-icons/icon-512.png": 512,
      "public/app-icons/maskable-192.png": 192,
      "public/app-icons/maskable-512.png": 512,
      "app/apple-icon.png": 180,
      "app/icon.png": 32,
    };
    for (const [path, size] of Object.entries(sizes)) {
      const { width, height } = await pixels(path);
      expect([path, width, height]).toEqual([path, size, size]);
    }
    expect(fs.existsSync("app/favicon.ico")).toBe(true);
  });

  it("any icons have transparent corners", async () => {
    for (const path of ["public/app-icons/icon-192.png", "public/app-icons/icon-512.png"]) {
      const { data, width } = await pixels(path);
      for (const [x, y] of [[0, 0], [width - 1, 0], [0, width - 1], [width - 1, width - 1]]) expect([path, x, y, data[(y * width + x) * 4 + 3]]).toEqual([path, x, y, 0]);
    }
  });

  it("maskable and apple icons are opaque", async () => {
    for (const path of ["public/app-icons/maskable-512.png", "app/apple-icon.png"]) {
      const { data } = await pixels(path);
      for (let i = 3; i < data.length; i += 4) if (data[i] !== 255) throw new Error(`${path}: alpha ${data[i]} at ${(i - 3) / 4}`);
    }
  });

  // Inside the safe zone (radius 0.4) with a margin, so a launcher whose mask is exactly the safe circle trims nothing.
  it("maskable statue stays inside the safe zone", async () => {
    const { data, width } = await pixels("public/app-icons/maskable-512.png");
    const c = width / 2, r = 0.39 * width;
    for (let y = 0; y < width; y++)
      for (let x = 0; x < width; x++) {
        if (Math.hypot(x + 0.5 - c, y + 0.5 - c) <= r) continue;
        const i = (y * width + x) * 4;
        for (let k = 0; k < 3; k++)
          if (Math.abs(data[i + k] - FIELD[k]) > 8) throw new Error(`non-field pixel outside the safe zone at ${x},${y}`);
      }
  });

  it("maskable icon is not just a field", async () => {
    const { data, width } = await pixels("public/app-icons/maskable-512.png");
    const c = width / 2, r = 0.4 * width;
    let inside = 0, art = 0;
    for (let y = 0; y < width; y++)
      for (let x = 0; x < width; x++) {
        if (Math.hypot(x + 0.5 - c, y + 0.5 - c) > r) continue;
        inside++;
        const i = (y * width + x) * 4;
        if ([0, 1, 2].some((k) => Math.abs(data[i + k] - FIELD[k]) > 8)) art++;
      }
    expect(art / inside).toBeGreaterThan(0.2);
  });

  it("the header emblem is the disc alone, without the field", () => {
    const svg = fs.readFileSync("public/app-icons/emblem.svg", "utf8");
    expect(svg).toMatch(/viewBox="120 120 784 784"/);
    expect(svg).not.toMatch(/#E8DCC3/i);
    expect(svg).not.toMatch(/c2pa/i);
  });

  it("the header emblem carries none of the editor's metadata or hidden layers", () => {
    const svg = fs.readFileSync("public/app-icons/emblem.svg", "utf8");
    expect(svg).not.toMatch(/inkscape|sodipodi/i);
    expect(svg).not.toMatch(/display:none/);
    expect(svg).not.toMatch(/\n[ \t]*\n/);
  });

  // The full drawing's thin line work blurs to grey at 32 pixels (3 such pixels); the bold outline gives about 50.
  it("the favicon draws the lamb with a bold dark outline, so it stands apart from the shepherd", async () => {
    const { data } = await pixels("app/icon.png");
    let dark = 0;
    for (let i = 0; i < data.length; i += 4) {
      const rgb = [data[i], data[i + 1], data[i + 2]];
      if (Math.max(...rgb) < 110 && Math.max(...rgb) - Math.min(...rgb) < 40) dark++;
    }
    expect(dark).toBeGreaterThan(25);
  });

  it("the field reaches the icon's edge, with no stroke along it", async () => {
    const { data, width } = await pixels("public/app-icons/maskable-512.png");
    for (const [x, y] of [[0, width / 2], [width / 2, 0], [width - 1, width / 2], [width / 2, width - 1], [0, 0]]) {
      const i = (y * width + x) * 4;
      expect([x, y, ...[0, 1, 2].map((k) => Math.abs(data[i + k] - FIELD[k]) <= 8)]).toEqual([x, y, true, true, true]);
    }
  });
});
